const html = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asText = value => Array.isArray(value)?value.map(asText).join('\n'):typeof value==='object'&&value!==null?JSON.stringify(value,null,2):String(value??'');
const paragraphs = value => asText(value).split('\n').filter(Boolean).map(s=>`<p>${html(s)}</p>`).join('');
const link = (url,label) => /^(https:\/\/|#)/.test(url||'')?`<a href="${html(url)}" ${url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${html(label)} <span aria-hidden="true">↗</span></a>`:html(label);
const days=TRAINING_WEEKS.flatMap(w=>w.days.map(d=>({...d,week:w.week,weekTitle:w.title,gate:w.gate})));
let training;
let pathWeek=0;
try { const saved=localStorage.getItem(TRAINING_KEY);training=saved?validateTraining(JSON.parse(saved)):freshTraining(); } catch { training=freshTraining(); }
let root=null,view=null,notify=()=>{},cleanup=null,sessionStarted=null,storageError=false;
let sqlId=SQL_LABS[0].id,pythonId=PYTHON_DRILLS[0].id,architectureId=ARCHITECTURE_DRILLS[0].id;
let sqlRuntime=null,pythonRuntime=null,sqlReady=false,sqlSchema=[],sqlVersion='',sqlResult=null,sqlPreview=null,sqlCheck=null,pythonResult=null;
let practicalHelp=null;
let busy=false,error='',revealed=new Set(),pythonConsent=false,traceStep=0,runGeneration=0;
const day=()=>days.find(d=>d.id===training.selectedDay)||days[0];
const labFor=type=>type==='sql'?SQL_LABS.find(l=>l.id===sqlId):PYTHON_DRILLS.find(l=>l.id===pythonId);
const exerciseKey=type=>`${type}:${labFor(type).id}`;
const sourceFor=type=>training.drafts[exerciseKey(type)]??labFor(type).starter??'';
function persist(){try{localStorage.setItem(TRAINING_KEY,JSON.stringify(trainingSnapshot(training)));window.dispatchEvent(new Event('tracecraft:progress-changed'));storageError=false;}catch{storageError=true;notify('Browser storage is full or unavailable. Export a backup before closing.');}return !storageError;}
function ensureToday(){if(training.session.date!==dayKey()){revealed.clear();sessionStarted=null;training.session={date:dayKey(),remaining:SESSION_SECONDS};persist();}}
function remaining(){return Math.max(0,training.session.remaining-(sessionStarted?(Date.now()-sessionStarted)/1000:0));}
function pause(){if(sessionStarted){training.session.remaining=remaining();sessionStarted=null;persist();}paintClock();}
function clock(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;}
function paintClock(){document.querySelectorAll('[data-training-clock]').forEach(el=>el.textContent=clock(remaining()));document.querySelectorAll('[data-training="timer"]').forEach(el=>el.textContent=sessionStarted?'Pause session':'Start / resume');const progress=document.querySelector('[data-session-progress]');if(progress)progress.style.width=`${100*(1-remaining()/SESSION_SECONDS)}%`;}
setInterval(()=>{if(!sessionStarted)return;if(document.hidden){pause();return;}if(remaining()===0){pause();notify('Two-hour session finished. Save your reflection and the next small step.');}paintClock();},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
window.addEventListener('pagehide',pause);
function sourceLinks(sources){return `<div class="training-sources">${(sources||[]).map(s=>link(typeof s==='string'?s:s.url,typeof s==='string'?new URL(s).hostname:(s.title||s.label||s.url))).join(' · ')}</div>`;}
function header(tag,title,description){return `<header class="section-intro"><h1>${html(title)}</h1><p class="runtime-tag">${html(tag)}</p><p>${html(description)}</p></header>`;}
function action(name,label,extra='',kind='ghost'){return `<button class="${kind}" data-training="${name}" ${extra}>${label}</button>`;}
function notice(){return storageError?'<div class="notice danger" role="alert">Progress cannot be saved in this browser. Export a backup before closing.</div>':'';}
function currentDayLink(){const route=day().route||'#sql';return route==='#training'?'#developer-path':route;}
function dailyNetworkPreview(){
 return `<svg class="daily-network" viewBox="0 0 500 130" aria-hidden="true"><defs><pattern id="daily-dots" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="currentColor" opacity=".22"/></pattern></defs><rect width="500" height="130" fill="url(#daily-dots)"/><g fill="none" stroke="#5d685c" stroke-width="1.5"><path d="M85 65H145M225 65C253 65 247 32 280 32M225 65C253 65 247 98 280 98M357 32C387 32 379 65 411 65M357 98C387 98 379 65 411 65"/></g><g fill="#202427" stroke="#3d4543"><rect x="14" y="45" width="72" height="40" rx="7"/><rect x="145" y="45" width="80" height="40" rx="7"/><rect x="280" y="12" width="77" height="40" rx="7"/><rect x="280" y="78" width="77" height="40" rx="7"/><rect x="411" y="45" width="75" height="40" rx="7"/></g><g fill="#dce2dc" text-anchor="middle" font-family="ui-monospace,monospace" font-size="10"><text x="50" y="69">Clients</text><text x="185" y="62">Load</text><text x="185" y="75">balancer</text><text x="318" y="36">Server A</text><text x="318" y="102">Server B</text><text x="448" y="69">Database</text></g><g fill="#c4f26d"><circle cx="116" cy="65" r="3"/><circle cx="259" cy="42" r="3"/><circle cx="387" cy="87" r="3"/></g></svg>`;
}
function homeView(){
 const independent=new Set(training.attempts.filter(a=>a.passed&&a.help==='independent').map(a=>`${a.type}:${a.exercise}`)).size;
 const reviewed=Object.values(training.reviews).filter(r=>r.stage>=2).length,due=dueReviews(training),current=day();
 const dayIndex=days.findIndex(d=>d.id===current.id)+1;
 const completedDays=days.filter(d=>training.done.includes(d.id)).length;
 return `<div class="daily-home">
 <header class="daily-heading"><div><h1>Your next two hours.</h1><p>A clear task. Time to focus. Something you can do yourself.</p></div><a class="daily-path-link" href="#developer-path"><span>Your developer path</span><strong>Week ${current.week} <span>/ 8</span></strong><span class="daily-path-track" role="progressbar" aria-label="Self-reported days completed" aria-valuemin="0" aria-valuemax="${days.length}" aria-valuenow="${completedDays}"><span style="width:${100*completedDays/days.length}%"></span></span><small>${completedDays} of ${days.length} days recorded <span aria-hidden="true">↗</span></small></a></header>
 <section class="course-entry"><div><h2>Build toward your next interview.</h2><p>Study the shared coding core, then follow backend and frontend/full-stack lessons with original checks and rehearsals.</p></div><a class="primary" href="#developer-path/course">Open interview course</a></section><div class="daily-start-grid">
 <section class="panel daily-assignment"><div class="daily-assignment-meta"><span class="chip green"><span class="dot"></span> Today’s assignment</span><span class="daily-day">Day ${String(dayIndex).padStart(2,'0')}</span></div><h2>${html(current.title)}</h2><p class="daily-week-tag">${html(current.weekTitle)}</p><div class="daily-task-copy">${paragraphs(current.task)}</div><div class="daily-assignment-bottom"><a class="primary" href="${html(currentDayLink())}">Open today’s work <span aria-hidden="true">→</span></a><a class="text-btn" href="#developer-path">Change assignment</a></div></section>
 <section class="panel daily-focus"><div class="daily-focus-title"><span class="eyebrow">Focus session</span><span class="daily-focus-dot" aria-hidden="true"></span></div><strong class="daily-clock" data-training-clock>${clock(remaining())}</strong><p>110 min of work · 10 min break</p><div class="session-progress"><div data-session-progress style="width:${100*(1-remaining()/SESSION_SECONDS)}%"></div></div><div class="daily-timer-actions">${action('timer',sessionStarted?'Pause session':'Start / resume','','primary')}${action('restart-timer','Reset','','text-btn')}</div><small>Pauses when you leave this tab. The timer never marks work complete.</small></section>
 </div>
 <div class="daily-evidence-strip" aria-label="Practice evidence"><div><span class="evidence-dot" aria-hidden="true"></span><strong>${independent}</strong><span>independent exercises</span></div><div><strong>${reviewed}</strong><span>repeated on separate days</span></div><div><strong>${due.length}</strong><span>reviews due</span></div><small>Practice evidence, at your pace.</small></div>
 <div class="daily-work-grid">
 <section class="panel daily-agenda"><div class="panel-head"><div><h2>The practice loop</h2></div><span class="chip">120 min</span></div><div class="session-blocks">${SESSION_BLOCKS.map((block,i)=>`<label class="session-block"><input type="checkbox" data-block="${html(block.id)}" ${(training.blocks[current.id]||[]).includes(block.id)?'checked':''}><span class="block-number">${String(i+1).padStart(2,'0')}</span><span><strong>${html(block.title)}</strong><small>${html(block.purpose||block.action)}</small></span><span class="block-minutes">${block.minutes}m</span></label>`).join('')}</div><small class="daily-agenda-note">Check off the work you finish. These are your own check-ins.</small></section>
 <div class="daily-side-stack">
 <section class="panel daily-design-preview"><div class="daily-preview-head"><span class="eyebrow">System design lab</span><span class="chip">Interactive</span></div><h2>Build it. Then break it.</h2><p>Connect components, send traffic, and find the weak point in your architecture.</p>${dailyNetworkPreview()}<div class="daily-preview-bottom"><span>Clients → servers → database</span><a class="text-btn" href="#design">Open the lab <span aria-hidden="true">↗</span></a></div></section>
 <section class="panel daily-review"><div class="panel-head"><div><h2>Come back to it</h2></div><span class="daily-review-count">${due.length}</span></div>${due.length?due.slice(0,5).map(r=>{const [type,id]=r.key.split(':');const item=(type==='sql'?SQL_LABS:type==='java'?JAVA_LABS:PYTHON_DRILLS).find(x=>x.id===id);return item?`<a class="review-link" href="#${type}/${html(id)}/review"><span><small>${html(type.toUpperCase())}</small>${html(item.title)}</span><span>Retry →</span></a>`:'';}).join(''):'<div class="daily-review-empty"><span class="daily-check-icon" aria-hidden="true">✓</span><div><strong>You’re clear for now.</strong><p>Your next review appears after a checked attempt.</p></div></div>'}<small>Retry after 1, 3, 7, then 14 days. An interval is a suggestion, not a mastery score.</small></section>
 <div class="daily-coaching"><span class="daily-coaching-mark" aria-hidden="true">↳</span><p>Stuck? Start with the smallest example. Predict the result. Test one thing.</p></div>
 </div></div>
 <section class="panel daily-reflection"><div><h2>What can you do now?</h2><p>${html(current.deliverable)}</p><p class="daily-reflection-hint">Save what you built, one mistake you fixed, and what you’ll retry. A file path or test result helps.</p></div><div><label class="sr-only" for="daily-notes">Daily evidence and reflection</label><textarea id="daily-notes" maxlength="6000" placeholder="I wrote…\nMy failing case was…\nNext time I will retry…">${html(training.notes[current.id]||'')}</textarea><div class="training-actions">${action('complete-day',training.done.includes(current.id)?'Session recorded ✓':'Record this session','','primary')}${action('next-day','Next day →','','text-btn')}</div><small>Session completion is self-reported. Code checks are tracked separately.</small></div></section>
 ${backupPanel()}</div>`;
}
function pathView(){
 if(location.hash.split('/')[1]==='course')return courseView(training);
 const weekNumber=pathWeek||day().week,w=TRAINING_WEEKS.find(week=>week.week===weekNumber),m=CURRICULUM_MODULES.find(module=>module.week===weekNumber);
 const checks=training.milestones['week'+weekNumber]||[];
 const lessonLink=([type,id])=>{const lesson=(type==='sql'?SQL_LABS:PYTHON_DRILLS).find(item=>item.id===id);return `<a href="#${type}/${html(id)}"><span>${type==='sql'?'SQL':'Python'}</span><strong>${html(lesson.title)}</strong><span aria-hidden="true">↗</span></a>`;};
 return `<header class="section-intro"><h1>Your path to a complete backend.</h1><p>One workout journal, built in stages. Work at your own pace, keep evidence, and repeat a milestone when the changed requirement is still difficult.</p></header>
 <section class="course-entry"><div><h2>Preparing for interviews?</h2><p>Follow the shared coding core, backend and frontend lessons, and saved mock interviews.</p></div><a class="primary" href="#developer-path/course">Open interview course</a></section><div class="path-context"><span>8 suggested weeks</span><span>SQL, Python, Java/Spring and operations</span><span>Milestones are self-assessed</span></div>
 <div class="curriculum-layout"><nav class="curriculum-nav" aria-label="Curriculum weeks">${CURRICULUM_MODULES.map(module=>`<button data-training="view-week" data-week="${module.week}" aria-pressed="${module.week===weekNumber}" class="${module.week===weekNumber?'selected':''}"><span>Week ${module.week} · ${html(module.phase)}</span><strong>${html(module.title)}</strong><small>${(training.milestones['week'+module.week]||[]).length}/${module.checks.length} self-checks</small></button>`).join('')}</nav>
 <div class="curriculum-detail"><section class="curriculum-overview"><p class="curriculum-location">Week ${weekNumber} of 8 · ${html(m.phase)}</p><h2>${html(m.title)}</h2><p>${html(m.overview)}</p><dl class="curriculum-facts"><div><dt>Practice environment</dt><dd>${html(m.environment)}</dd></div><div><dt>Recommended prerequisite</dt><dd>${m.prerequisites.length?'Evidence from week '+m.prerequisites.join(', '):'Start here. No prerequisite.'}</dd></div></dl><ul class="curriculum-concepts">${m.concepts.map(concept=>`<li>${html(concept)}</li>`).join('')}</ul></section>
 ${m.lessons.length?`<section class="curriculum-section"><h3>Practice the building blocks</h3><p>These checks execute in the browser. The project work below runs in the stated environment.</p><div class="curriculum-lessons">${m.lessons.map(lessonLink).join('')}</div></section>`:''}
 <section class="curriculum-section"><h3>Seven sessions, one concrete outcome</h3><p>Select a session to make it your daily assignment. A checked-off session remains your own record.</p><div class="week-days">${w.days.map((d,i)=>`<button class="day-assignment ${training.selectedDay===d.id?'selected':''}" data-training="select-day" data-id="${html(d.id)}"><span>${training.done.includes(d.id)?'✓':i+1}</span><span><strong>${html(d.title)}</strong><small>${html(d.deliverable)}</small></span><span aria-hidden="true">→</span></button>`).join('')}</div></section>
 <section class="curriculum-section"><h3>What to keep as evidence</h3><ul>${m.evidence.map(item=>`<li>${html(item)}</li>`).join('')}</ul><details><summary>Counterexamples to investigate</summary><ul>${m.pitfalls.map(item=>`<li>${html(item)}</li>`).join('')}</ul></details></section>
 <section class="curriculum-section milestone-review"><h3>Defend this milestone</h3><p>${html(m.gate)}</p><p class="small-note" data-milestone-count>${checks.length}/${m.checks.length} self-checks recorded. These are reflection prompts, not an automated pass or a hiring score.</p>${m.checks.map(([id,label])=>`<label class="milestone-check"><input type="checkbox" data-milestone="week${weekNumber}" value="${html(id)}" ${checks.includes(id)?'checked':''}><span>${html(label)}</span></label>`).join('')}<label for="milestone-notes">Evidence links, limitations, and next retry</label><textarea id="milestone-notes" data-explanation="milestone:week-${weekNumber}" maxlength="6000" placeholder="Link a test, commit, migration or investigation. State what it proves and what remains untested.">${html(training.explanations['milestone:week-'+weekNumber]||'')}</textarea><p class="small-note">Saved locally as you type. <a href="#progress">Sign in and review sync</a> to keep an account copy.</p></section>${sourceLinks(w.resources)}</div></div>`;
}
function resultTables(results){if(!results?.length)return '<p class="training-muted">Statement completed. No rows were returned.</p>';return results.map((r,i)=>`<div class="result-table-wrap"><table class="result-table"><caption>Result ${i+1} · ${r.values?.length||0} displayed rows${r.truncated?' · output limited':''}</caption><thead><tr>${(r.columns||[]).map(c=>`<th scope="col">${html(c)}</th>`).join('')}</tr></thead><tbody>${(r.values||[]).map(row=>`<tr>${row.map(v=>`<td>${v===null?'<em>NULL</em>':html(typeof v==='object'?JSON.stringify(v):v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('');}
function checkResults(check){if(!check)return '';const firstError=check.checks.find(item=>!item.passed&&item.error)?.error;return `<section class="check-results" aria-live="polite"><h3>${check.passed?'Checks pass ✓':'A check found a problem'}</h3>${!check.passed&&isGuided(labFor('sql'))?`<div class="notice danger" role="alert">${firstError?`<p>${html(sqlErrorGuide(firstError))}</p><p>${html(firstError)}</p>`:'<p>The query ran, but its result did not match the requirement. Open a failed example below to compare Expected and Actual. Check column names, row order, and exact boundaries.</p>'}${action('edit-again','Back to my query','','ghost')}</div>`:''}${check.checks.map(c=>`<details class="fixture-result"><summary><span class="${c.passed?'pass':'fail'}">${c.passed?'✓':'×'}</span> ${html(c.label)}</summary>${c.error?`<pre class="code-output">${html(c.error)}</pre>`:''}<strong>Expected</strong>${resultTables(c.expected)}<strong>Actual</strong>${resultTables(c.actual)}</details>`).join('')}<p>These checks use the starting data and changed examples. They record practice. Explain the query and try another example before considering it learned.</p></section>`;}
const hintCount=key=>[...revealed].filter(value=>value.startsWith(key+':hint:')).length;
function helpPanel(type){const l=labFor(type),key=exerciseKey(type);const panel=practicalHelpPanel(type,l,{level:practicalHelp?.key===key?practicalHelp.level:null,helpLabel:draftAssistance(training,key)});if(panel!==null)return (busy?panel.replaceAll('type="button"','type="button" disabled'):panel)+`<section class="panel"><h2>Choose the kind of attempt</h2><div class="training-actions">${action('blank','Fresh starter',`data-type="${type}" ${busy?'disabled':''}`)}${action('practical-blank','Blank editor',`data-type="${type}" ${busy?'disabled':''}`)}${action('bug','Debug a deliberate bug',`data-type="${type}" ${busy?'disabled':''}`)}${training.drafts['archive:'+key]?action('previous-draft','Review previous draft',`data-type="${type}" ${busy?'disabled':''}`):''}</div>${revealed.has(key+':previous')?`<pre class="code-output">${html(training.drafts['archive:'+key])}</pre>`:''}<p>Debugging and source tracing help you investigate. They do not establish that you wrote a fresh solution from blank.</p></section>`;const hints=Array.isArray(l.hints)?l.hints:[l.hint||'State the input, the expected result, and the smallest operation that makes progress.'];return `<section class="panel training-help"><div class="panel-head"><h2>Help, when you need it</h2><span class="chip">${html(helpFor(training,key))} today</span></div><p>Try first. Using help is part of learning; the record should show it.</p><div class="training-actions">${action('hint',hintCount(key)?'Show next hint':'Show a hint',`data-type="${type}" ${busy||hintCount(key)>=hints.length?'disabled':''}`)}${action('solution','Study a worked solution',`data-type="${type}" ${busy?'disabled':''}`)}${action('bug','Load a deliberate bug',`data-type="${type}" ${busy?'disabled':''}`)}${action('blank','Start a fresh attempt',`data-type="${type}" ${busy?'disabled':''}`,'text-btn')}${action('outside-help','I used outside help',`data-type="${type}" ${busy?'disabled':''}`,'text-btn')}${training.drafts['archive:'+key]?action('previous-draft','See previous draft',`data-type="${type}" ${busy?'disabled':''}`,'text-btn'):''}</div><small>Assistance includes help used here or reported by you. A continued saved answer does not earn a fresh review pass.</small>${revealed.has(key+':previous')?`<pre class="code-output">${html(training.drafts['archive:'+key])}</pre>`:''}${revealed.has(`${key}:hint`)?`<div class="notice">${hints.slice(0,hintCount(key)).map(h=>paragraphs(h)).join('')}</div>`:''}${revealed.has(`${key}:solution`)?`<div class="worked-solution"><h3>Worked solution</h3><pre class="code-output">${html(l.solution)}</pre>${paragraphs(l.explanation)}<p><strong>Cost / trade-off:</strong> ${html(l.complexity)}</p></div>`:''}</section>`;}
function explanationPanel(type){const key=exerciseKey(type),lesson=lessonForTask(type,labFor(type).id);if(lesson)return `<section class="panel"><h2>Explain what you learned</h2><p>${html(lesson.recap)}</p><label for="practice-explanation">Your explanation (optional)</label><textarea id="practice-explanation" data-explanation="${html(key)}" maxlength="6000" placeholder="What I tried and what it displayed...">${html(training.explanations[key]||'')}</textarea><small>Saved as you type. This is your own reflection.</small></section>`;return `<section class="panel"><h2>Explain it without reading the code.</h2><p>What does it do? Why is it correct? How does it handle an empty input, a duplicate, or a failure? Name one trade-off.</p><label class="sr-only" for="practice-explanation">Your explanation</label><textarea id="practice-explanation" data-explanation="${html(key)}" maxlength="6000" placeholder="What… Why… How…">${html(training.explanations[key]||'')}</textarea><small>Saved in this browser as you type. Your explanation is self-assessed.</small></section>`;}
const isGuided=lab=>Boolean(lessonForTask('python',lab.id)||lessonForTask('sql',lab.id));
function sqlView(){const l=labFor('sql');return `${practicalLabGuide('sql',l,training)}${beginnerLabGuide('sql',l)}${isGuided(l)||l.curriculum==='practical'?'':header('Real SQLite · a disposable practice database','Write the query yourself.','Start with the requirement, predict the rows, then run real SQL. Foreign keys are enabled. This lab uses SQLite, not a MySQL or PostgreSQL server.')}<div class="training-toolbar"><label for="sql-select">Exercise</label><select id="sql-select" ${busy?'disabled':''}>${SQL_LABS.map((c,i)=>`<option value="${html(c.id)}" ${c.id===sqlId?'selected':''}>${i+1}. ${html(c.title)}</option>`).join('')}</select><span class="chip">${sqlReady?`SQLite ${html(sqlVersion)}`:error?'Reset required':'Loading database…'}</span>${action('reset-sql','Reset practice database',busy?'disabled':'')}</div><div class="workbench-grid"><section class="panel workbench-editor"><div class="eyebrow">${html(l.topic)}</div><h2>${html(l.title)}</h2>${paragraphs(l.prompt)}<section class="input-contract"><h3>Inputs and required result</h3>${paragraphs(l.contract)}<pre class="code-output">${html(asText(l.schema))}</pre></section>${isGuided(l)&&sqlPreview?`<details class="beginner-input-data" open><summary>Starting rows in the database</summary>${resultTables(sqlPreview)}</details><details class="practice-examples" open><summary>Expected result for these starting rows</summary>${resultTables(l.fixtures[0].expected)}</details>`:''}<label for="sql-editor">Your SQL</label><textarea id="sql-editor" ${busy?'readonly':''} class="workbench-code" spellcheck="false" autocapitalize="off" autocomplete="off" maxlength="20000" placeholder="-- Write your first statement here.">${html(sourceFor('sql'))}</textarea><div class="training-actions">${action('run-sql',busy?'Working…':'Run SQL',busy||!sqlReady?'disabled':'','primary')}${action('check-sql','Check my answer',busy||!sqlReady?'disabled':'')}${busy?action('cancel','Cancel','','text-btn'):''}</div><small>⌘ / Ctrl + Enter to run. Each check uses fresh data, including changed fixtures.</small></section><section class="panel result-panel"><h2>Database & results</h2><p class="training-muted">SELECT reads data. Write statements such as UPDATE can change this practice database. Check my answer uses separate fresh data. Reset restores the starting tables and rows while keeping your code draft.</p>${error?`<div class="notice danger" role="alert">${isGuided(l)&&view==='sql'?`<p>${html(sqlErrorGuide(error))}</p>`:''}${html(error)}</div>`:''}${sqlResult?resultTables(sqlResult.results):sqlCheck?'':'<div class="workbench-empty"><span aria-hidden="true">▤</span><h3>Make a prediction first.</h3><p>Which rows should this query return? Your actual results will appear here.</p></div>'}${checkResults(sqlCheck)}${sqlCheck?.passed?beginnerNextLink('sql',l.id):''}<details><summary>Current table definitions</summary>${sqlSchema.length?sqlSchema.map(s=>`<pre class="code-output">${html(s.sql)}</pre>`).join(''):'<p>This workspace starts empty. Create the tables described in the contract.</p>'}</details></section></div>${helpPanel('sql')}${explanationPanel('sql')}${sourceLinks(l.sources)}`;}
function beginnerNextLink(type,id){const lesson=lessonForTask(type,id);if(!lesson)return '';const next=BEGINNER_LESSONS[BEGINNER_LESSONS.indexOf(lesson)+1];return `<div class="beginner-task-next"><a href="#beginner/${lesson.id}">Review this lesson</a>${next?`<a href="#beginner/${next.id}">Next lesson: ${html(next.title)}</a>`:'<a href="#beginner">Back to beginner lessons</a>'}</div>`;}
function beginnerLabGuide(type,lab){const lesson=lessonForTask(type,lab.id);if(!lesson)return '';return `<section class="beginner-lab-guide"><a href="#beginner/${lesson.id}">Back to the lesson: ${html(lesson.title)}</a><h1>${html(lab.title)}</h1><p>${type==='python'?'A line beginning with # is a comment: a note Python ignores.':'A line beginning with -- is a comment: a note SQL ignores. The table and rows are already prepared for this task.'}</p><p>1. Read the task. 2. Type your code. 3. Run it. 4. Check my answer.</p>${type==='python'&&lab.starter.startsWith('def ')?'<p><strong>A function definition may display nothing when you choose Run.</strong> That is normal: it has not been called yet. Check my answer supplies inputs and checks the returned values. You do not need print() or input() for this task.</p>':''}<p><strong>Run</strong> shows what your code does. <strong>Check my answer</strong> tests whether it does what this task asks. You can edit and retry as often as you need.</p></section>`;}
function pythonView(){const l=labFor('python'),frames=pythonResult?.frames||[],frame=frames[traceStep];return `${practicalLabGuide('python',l,training)}${beginnerLabGuide('python',l)}${isGuided(l)||l.curriculum==='practical'?'':header('Real Python · functions, classes and collections','Build fluency, then solve unfamiliar problems.','Write Python from a blank or minimal starter, check its behavior, and inspect the source-linked trace. This is separate from the original Mini-Python visual lab.')}<div class="training-toolbar"><label for="python-select">Exercise</label><select id="python-select" ${busy?'disabled':''}>${PYTHON_DRILLS.map((c,i)=>`<option value="${html(c.id)}" ${c.id===pythonId?'selected':''}>${i+1}. ${html(c.title)}</option>`).join('')}</select><span class="chip">${isGuided(l)?'Python in your browser':'CPython via Pyodide · browser execution'}</span></div>${!pythonConsent?`<div class="notice"><strong>Load the Python runtime when you are ready.</strong><p>The first run downloads the pinned Pyodide runtime from jsDelivr. The CDN receives normal request metadata; this app does not send it your code. Your code runs in a browser worker. An internet connection is needed for the initial download.</p>${action('enable-python','Load Python & enable practice','','primary')}</div>`:''}<div class="workbench-grid"><section class="panel workbench-editor"><div class="eyebrow">${html(l.topic||'PYTHON FOUNDATIONS')}</div><h2>${html(l.title)}</h2>${paragraphs(l.prompt)}<section class="input-contract"><h3>Inputs and required result</h3>${paragraphs(l.contract)}</section><details class="practice-examples" ${isGuided(l)?'open':''}><summary>Examples and edge cases to consider</summary><ul>${l.fixtures.map(fixture=>`<li><strong>${html(fixture.label)}:</strong> ${html(fixture.assertion)}</li>`).join('')}</ul></details><label for="python-editor">Your Python</label>${isGuided(l)?`<p class="training-muted">Use four spaces to indent a line. Tab moves to the next control. Select lines and use these buttons to adjust them.</p><div class="training-actions">${action('indent-code','Indent 4 spaces',busy?'disabled':'')}${action('unindent-code','Remove indentation',busy?'disabled':'')}</div>`:''}<textarea id="python-editor" ${busy?'readonly':''} class="workbench-code" spellcheck="false" autocapitalize="off" autocomplete="off" maxlength="12000">${html(sourceFor('python'))}</textarea><div class="training-actions">${action('run-python',busy?'Running / loading…':isGuided(l)?'Run my code':'Run & trace',busy||!pythonConsent?'disabled':'','primary')}${action('check-python','Check my answer',busy||!pythonConsent?'disabled':'')}${busy?action('cancel','Cancel','','text-btn'):''}</div><small>First run can take a moment. Infinite loops are stopped by a worker timeout.</small></section><section class="panel result-panel"><h2>${isGuided(l)?'Your result':'Output & trace'}</h2>${error?`<div class="notice danger" role="alert">${isGuided(l)&&view==='sql'?`<p>${html(sqlErrorGuide(error))}</p>`:''}${html(error)}</div>`:''}${pythonResult?`<pre class="code-output">${html(pythonResult.stdout||'(No printed output)')}</pre>${pythonResult.stderr?`<pre class="code-output danger">${html(pythonResult.stderr)}</pre>`:''}${pythonResult.error?isGuided(l)?`<div class="notice danger" role="alert">${html(pythonErrorGuide(pythonResult.error))}</div><details class="practice-error-details" open><summary>Error details from Python</summary><pre class="code-output danger">${html(pythonResult.error)}</pre></details>`:`<pre class="code-output danger">${html(pythonResult.error)}</pre>`:''}${typeof pythonResult.passed==='boolean'?`<div role="status" class="notice ${pythonResult.passed?'':'danger'}">${pythonResult.passed?isGuided(l)?'Your code does what this task asks. Explain what you learned below.':'Assertions pass. Now explain your solution.':isGuided(l)?pythonFailureKind(pythonResult.error)==='runtime'?'Python could not complete this check. Your draft is preserved. Follow the loading guidance above and retry.':'Your code needs another try. Compare the output with the task and read the error details shown above.':'An assertion or execution failed. Find the smallest failing case.'}</div>`:''}${isGuided(l)&&typeof pythonResult.passed==='boolean'?'<p class="training-muted">This check verifies results, not which Python instructions you used.</p>':''}${isGuided(l)&&pythonResult.error?action('edit-again','Back to my code','','ghost'):''}${pythonResult.passed?beginnerNextLink('python',l.id):''}${pythonResult.truncated?'<p class="training-muted">Output or tracing reached its display limit.</p>':''}`:'<div class="workbench-empty"><span aria-hidden="true">{ }</span><h3>Small programs. Real behavior.</h3><p>Start with one example, then change its input.</p></div>'}${frames.length?`<details class="python-trace-details" ${isGuided(l)||l.curriculum==='practical'?'':'open'}><summary>See how Python followed your code (optional)</summary><div class="trace-controls">${action('trace-prev','← Back',traceStep===0?'disabled':'')}${action('trace-next','Next →',traceStep>=frames.length-1?'disabled':'')}<small>Frame ${traceStep+1}/${frames.length}</small></div><p class="training-muted">${frame.event==='line'?'State before':'State at '+html(frame.event)+' on'} source line ${html(frame.line)} · ${html(frame.function||'program')} · ${html(frame.stage||'program')}. Values are bounded text snapshots.</p><pre class="code-output">${html(asText(frame.locals))}</pre></details>`:''}<details><summary>How this answer is checked (Python test code)</summary><pre class="code-output">${html(l.tests)}</pre></details></section></div>${helpPanel('python')}${explanationPanel('python')}${sourceLinks(l.sources)}`;}
function architectureView(){const d=ARCHITECTURE_DRILLS.find(x=>x.id===architectureId),key=`architecture:${d.id}`;return `${header('What, why, how, and what if it fails','Explain the design.','Practice with a concrete scenario. Make a choice, explain the cost, and follow one request through the system. These are self-assessed design drills.')}<div class="training-toolbar"><label for="architecture-select">Scenario</label><select id="architecture-select">${ARCHITECTURE_DRILLS.map(x=>`<option value="${html(x.id)}" ${x.id===d.id?'selected':''}>${html(x.title)}</option>`).join('')}</select></div><div class="training-two-col"><section class="panel"><div class="eyebrow">Design prompt</div><h2>${html(d.title)}</h2>${paragraphs(d.scenario)}<ol class="design-questions">${(d.questions||[]).map(q=>`<li>${html(q)}</li>`).join('')}</ol><label for="design-answer">Your explanation, before the example</label><textarea id="design-answer" data-explanation="${html(key)}" maxlength="6000" placeholder="I would choose… because…\nThe request goes from… to…\nIf this dependency fails…\nThe trade-off is…">${html(training.explanations[key]||'')}</textarea>${action('model-answer','Compare with a worked explanation','','primary')}</section><section class="panel"><h2>Reflection checklist</h2>${(d.rubric||[]).map(item=>`<label class="design-check"><input type="checkbox"><span>${html(item)}</span></label>`).join('')}<div class="deliverable"><strong>Failure drill</strong>${paragraphs(d.failureDrill)}</div><p class="training-muted">Speak for 2-3 minutes, then answer the follow-up. Check these yourself; TraceCraft does not automatically grade design answers.</p></section></div>${revealed.has(key)?`<section class="panel worked-solution"><h2>One defensible approach</h2>${paragraphs(d.modelAnswer)}<div class="notice">Other designs can be valid. Compare their assumptions, correctness, operating cost, and failure behavior.</div></section>`:''}${sourceLinks(d.sources)}`;}
function backupPanel(){return `<section class="training-backup"><div><strong>Your progress belongs to you.</strong><p>Saved in this browser. The latest 500 checks are retained. Export regularly to keep earlier attempts or move devices. Import replaces this training workspace. <a href="#progress">Sync an account or back up all workspaces</a>.</p></div><div class="training-actions">${action('export-training','Export progress')}${action('import-training','Import backup')}<input class="sr-only" type="file" id="training-import" accept="application/json,.json" aria-label="Choose a TraceCraft training backup"></div></section>`;}
export function trainingView(route){ensureToday();const content=route==='apis'?apiCourseView(training):route==='tcs'?tcsView(training):route==='coach'?coachView(training):route==='java'?javaView(training):route==='sql'?sqlView():route==='python'?pythonView():route==='architecture'?architectureView():route==='developer-path'?pathView():homeView();return `<div class="training-wrap ${['sql','python'].includes(route)&&labFor(route).curriculum==='practical'?'training-practical':''} ${['sql','python'].includes(route)&&isGuided(labFor(route))?'training-guided':''}" data-training-root>${notice()}${content}</div>`;}
function redraw(){if(!root||!view)return;const current=root.querySelector('[data-training-root]');if(current)current.outerHTML=trainingView(view);paintClock();}
async function initializeSQL(){const gen=++runGeneration;sqlRuntime?.dispose();sqlRuntime=new SqlRuntime();sqlReady=false;sqlSchema=[];sqlVersion='';sqlResult=null;sqlPreview=null;sqlCheck=null;error='';redraw();try{const result=await sqlRuntime.initialize(sqlId);if(gen!==runGeneration)return;sqlSchema=result.schema||[];sqlVersion=result.sqliteVersion||'';if(labFor('sql').previewQuery){const preview=await sqlRuntime.run(labFor('sql').previewQuery);if(gen!==runGeneration)return;sqlPreview=preview.results;}sqlReady=true;}catch(e){if(gen!==runGeneration)return;error=e.message;}redraw();}
async function runExercise(type,check){const current=labFor(type);if(current.curriculum==='practical'&&current.prediction&&!(training.explanations[`prediction:${type}:${current.id}`]||'').trim()){notify('Write your best prediction before running. One sentence is enough; it is not graded.');root?.querySelector('#practical-prediction')?.focus();return;}const gen=++runGeneration;error='';busy=true;const code=sourceFor(type),exercise=labFor(type).id;redraw();try{
 if(type==='sql'){if(check){const result=await sqlRuntime.check(code,exercise);if(gen!==runGeneration)return;sqlCheck=result;recordAttempt(training,{type,exercise,passed:result.passed,code,result});persist();signalResult(result.passed===true,'sql-check');}else{const result=await sqlRuntime.run(code);if(gen!==runGeneration)return;sqlResult=result;sqlSchema=result.schema||sqlSchema;sqlCheck=null;}}
 else{pythonRuntime??=new PythonRuntime();const result=await pythonRuntime.run(code,{trace:true,...(check?{tests:labFor(type).tests}:{})});if(gen!==runGeneration)return;pythonResult=result;traceStep=0;if(check){recordAttempt(training,{type,exercise,passed:result.passed===true&&!result.error,code,result});persist();signalResult(result.passed===true&&!result.error,'python-check');}}
 }catch(e){if(gen!==runGeneration)return;error=e.message;if(check){recordAttempt(training,{type,exercise,passed:false,code,result:{error:e.message}});persist();signalResult(false,type+'-check');}if(type==='sql'){sqlReady=Boolean(sqlRuntime?.initialized);if(sqlReady)error+=' Earlier statements may have changed the practice database; inspect it or Reset before rerunning the whole script.';}}
 finally{if(gen===runGeneration){busy=false;redraw();const heading=root?.querySelector('.result-panel h2');heading?.setAttribute('tabindex','-1');heading?.focus();heading?.scrollIntoView({block:'start',behavior:'instant'});}}
}
function downloadBackup(){const blob=new Blob([JSON.stringify({format:'tracecraft-training',version:1,exportedAt:new Date().toISOString(),data:{...trainingSnapshot(training),session:{date:dayKey(),remaining:remaining()}}},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`tracecraft-training-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Training backup downloaded. It includes your code and personal notes.');}
async function onClick(event){const button=event.target.closest('[data-training]');if(!button||!root?.contains(button))return;const action=button.dataset.training,type=button.dataset.type;
 if(action==='practical-help'||action==='practical-documentation'){if(busy)return;const level=action==='practical-documentation'?'documentation':button.dataset.level;recordAssistance(training,exerciseKey(type),level);if(level!=='documentation')practicalHelp={key:exerciseKey(type),level};persist();redraw();return;}
 if(action==='practical-stop'){practicalHelp=null;redraw();return;}
 if(action==='practical-blank'){if(busy)return;startFreshAttempt(training,exerciseKey(type),'');practicalHelp=null;persist();redraw();return;}
 if(action==='edit-again'){const editor=root.querySelector('#'+view+'-editor');editor?.focus();editor?.scrollIntoView({block:'center',behavior:'instant'});return;}
 if(action==='indent-code'||action==='unindent-code'){const editor=root.querySelector('#python-editor');if(!editor||busy)return;const edited=indentCode(editor.value,editor.selectionStart,editor.selectionEnd,action==='unindent-code');editor.value=edited.source;editor.dispatchEvent(new Event('input',{bubbles:true}));editor.focus();editor.setSelectionRange(edited.start,edited.end);return;}
 if(action==='timer'){ensureToday();if(sessionStarted)pause();else{if(remaining()<=0)training.session.remaining=SESSION_SECONDS;sessionStarted=Date.now();persist();}paintClock();return;}
 if(action==='restart-timer'){pause();training.session.remaining=SESSION_SECONDS;persist();paintClock();return;}
 if(action==='view-week'){pathWeek=Number(button.dataset.week);redraw();root.querySelector('[data-week="'+pathWeek+'"]')?.focus();return;}
 if(action==='select-day'){training.selectedDay=button.dataset.id;persist();location.hash='#today';return;}
 if(action==='next-day'){const i=days.findIndex(d=>d.id===training.selectedDay);training.selectedDay=days[Math.min(days.length-1,i+1)].id;persist();redraw();return;}
 if(action==='complete-day'){if(!(training.notes[day().id]||'').trim()){notify('Write one concrete piece of evidence before completing this day.');root.querySelector('#daily-notes')?.focus();return;}if(!training.done.includes(day().id))training.done.push(day().id);persist();redraw();notify('Session reflection saved. Completion is your own check-in.');return;}
 if(action==='export-training'){downloadBackup();return;}
 if(action==='import-training'){root.querySelector('#training-import').click();return;}
 if(action==='reset-sql'){await initializeSQL();return;}
 if(action==='run-sql'||action==='check-sql'){await runExercise('sql',action==='check-sql');return;}
 if(action==='enable-python'){pythonConsent=true;redraw();notify('Python is enabled. Run your program to load the runtime.');return;}
 if(action==='run-python'||action==='check-python'){await runExercise('python',action==='check-python');return;}
 if(action==='cancel'){++runGeneration;sqlRuntime?.dispose();pythonRuntime?.dispose();sqlRuntime=null;pythonRuntime=null;sqlReady=false;busy=false;error=view==='sql'?'Run cancelled. Reset the SQL database before another run.':'Python run cancelled. You can edit and run again.';redraw();const heading=root?.querySelector('.result-panel h2');heading?.setAttribute('tabindex','-1');heading?.focus();return;}
 if(['hint','solution','bug','blank','outside-help','previous-draft'].includes(action)){const key=exerciseKey(type),lab=labFor(type);if(action==='hint')revealed.add(key+':hint:'+hintCount(key));if(action==='hint'||action==='solution'){recordHelp(training,key,action);revealed.add(`${key}:${action}`);}if(action==='bug'){recordHelp(training,key,'hint');training.practiceKinds[key]='debug';training.drafts[key]=lab.bug;}if(action==='blank'){startFreshAttempt(training,key,lab.starter||'');for(const value of [...revealed])if(value.startsWith(key+':hint:'))revealed.delete(value);revealed.delete(key+':hint');revealed.delete(key+':solution');revealed.delete(key+':previous');}if(action==='outside-help')recordHelp(training,key,'hint');if(action==='previous-draft'){recordHelp(training,key,'solution');revealed.add(key+':previous');}persist();if(type==='sql'){sqlCheck=null;sqlResult=null;}else pythonResult=null;redraw();return;}
 if(action==='trace-prev'||action==='trace-next'){traceStep=Math.max(0,Math.min((pythonResult?.frames?.length||1)-1,traceStep+(action==='trace-next'?1:-1)));redraw();return;}
 if(action==='model-answer'){const key=`architecture:${architectureId}`;if(!(training.explanations[key]||'').trim()){notify('Write your initial choice and reason first; then compare it with the example.');root.querySelector('#design-answer')?.focus();return;}revealed.add(key);redraw();}
}
function onInput(event){const el=event.target;if(el.id==='sql-editor'||el.id==='python-editor'){training.drafts[exerciseKey(el.id==='sql-editor'?'sql':'python')]=el.value;persist();if(sqlCheck||sqlResult||pythonResult||error){sqlCheck=null;sqlResult=null;pythonResult=null;error='';const results=root.querySelector('.result-panel');if(results)results.innerHTML='<h2>Results need a new run</h2><p>Your code changed. Run or check this version to see its output.</p>'; }}if(el.dataset.explanation){training.explanations[el.dataset.explanation]=el.value;persist();}if(el.id==='daily-notes'){training.notes[day().id]=el.value;persist();}}
async function onChange(event){const el=event.target;if(el.id==='practical-lab-mode'){if(busy){redraw();return;}if(['learn','practice','interview'].includes(el.value))training.coach.mode=el.value;if(el.value==='learn')recordAssistance(training,exerciseKey(view),'nudge');persist();redraw();return;}if(el.dataset.milestone){const key=el.dataset.milestone,old=training.milestones[key]||[];training.milestones[key]=el.checked?[...new Set([...old,el.value])]:old.filter(value=>value!==el.value);persist();const counter=root.querySelector('[data-milestone-count]');if(counter)counter.textContent=training.milestones[key].length+'/3 self-checks recorded. These are reflection prompts, not an automated pass or a hiring score.';const navCounter=root.querySelector('[data-week="'+key.replace('week','')+'"] small');if(navCounter)navCounter.textContent=training.milestones[key].length+'/3 self-checks';return;}if(el.id==='sql-select'){sqlId=el.value;location.hash=`#sql/${sqlId}`;}if(el.id==='python-select'){pythonId=el.value;location.hash=`#python/${pythonId}`;}if(el.id==='architecture-select'){architectureId=el.value;redraw();}if(el.dataset.block){const id=day().id;training.blocks[id]=el.checked?[...new Set([...(training.blocks[id]||[]),el.dataset.block])]:(training.blocks[id]||[]).filter(x=>x!==el.dataset.block);persist();}if(el.id==='training-import'&&el.files[0]){try{const file=el.files[0];if(file.size>64_000_000)throw new Error('Backup is too large (maximum 64 MB).');const backup=JSON.parse(await file.text());if(backup.format!=='tracecraft-training'||backup.version!==1)throw new Error('Choose a TraceCraft training backup JSON file.');const next=validateTraining(backup.data);pause();training=next;persist();redraw();notify('Training progress imported. Your original visual-lab progress is unchanged.');}catch(e){notify(e.message);}}}
function onKey(event){if((event.metaKey||event.ctrlKey)&&event.key==='Enter'&&['sql-editor','python-editor'].includes(event.target.id)){event.preventDefault();if(!busy&&((view==='sql'&&sqlReady)||(view==='python'&&pythonConsent)))runExercise(view,false);}}
export function unmountTraining(){unmountApiCourse();practicalHelp=null;unmountTcs();unmountCoach();unmountJava();unmountCourse();pause();cleanup?.();cleanup=null;root=null;view=null;++runGeneration;sqlRuntime?.dispose();pythonRuntime?.dispose();sqlRuntime=null;pythonRuntime=null;sqlReady=false;busy=false;error='';pythonResult=null;traceStep=0;}
export function mountTraining(element,route,onNotify){root=element;view=route;notify=onNotify;const id=location.hash.split('/')[1];if(route==='sql'&&SQL_LABS.some(l=>l.id===id))sqlId=id;if(route==='python'&&PYTHON_DRILLS.some(l=>l.id===id))pythonId=id;if(['sql','python'].includes(route)){const key=exerciseKey(route),review=training.reviews[key];if(review?.due<=dayKey()&&training.fresh[key]!==dayKey()){startFreshAttempt(training,key,labFor(route).starter||'');for(const value of [...revealed])if(value.startsWith(key+':hint:'))revealed.delete(value);revealed.delete(key+':hint');revealed.delete(key+':solution');revealed.delete(key+':previous');persist();notify('Fresh review started. Your previous draft is preserved under Help.');}}if(['sql','python'].includes(route)&&labFor(route).curriculum==='practical'&&training.coach.mode==='learn'){recordAssistance(training,exerciseKey(route),'nudge');persist();}root.addEventListener('click',onClick);root.addEventListener('input',onInput);root.addEventListener('change',onChange);root.addEventListener('keydown',onKey);const currentRoot=root;cleanup=()=>{currentRoot.removeEventListener('click',onClick);currentRoot.removeEventListener('input',onInput);currentRoot.removeEventListener('change',onChange);currentRoot.removeEventListener('keydown',onKey);};if(route==='sql')initializeSQL();else redraw();if(route==='java')mountJava(root,training,persist,onNotify);if(route==='coach')mountCoach(root,training,persist,onNotify);if(route==='tcs')mountTcs(root,training,persist,onNotify);if(route==='apis')mountApiCourse(root,training,persist,onNotify);if(route==='developer-path'&&location.hash.split('/')[1]==='course')mountCourse(root,onNotify);}

export function trainingSearchItems(){return [...apiCourseSearchItems(),...tcsSearchItems(),...coachSearchItems(),...courseSearchItems(),...JAVA_LABS.map(l=>({title:l.title,detail:'Java browser practice',hash:'#java/'+l.id})),...SQL_LABS.map(l=>({title:l.title,detail:'SQL · '+l.topic,hash:'#sql/'+l.id})),...PYTHON_DRILLS.map(l=>({title:l.title,detail:l.topic||'Python foundations',hash:'#python/'+l.id})),{title:'Daily two-hour session',detail:'Practice, review, journal, backup',hash:'#today'},{title:'Developer path',detail:'Database operations, APIs, projects, microservices',hash:'#developer-path'}];}

export const readArcadeProgress=()=>training.arcade;
export function saveArcadeProgress(next){training.arcade=next;persist();return !storageError;}
initializeCoach(()=>training,persist);
initializeCourse(()=>training,persist,task=>{const lessons=task.type==='sql'?SQL_LABS:task.type==='java'?JAVA_LABS:PYTHON_DRILLS;const lesson=lessons.find(item=>item.id===task.id);if(lesson){startFreshAttempt(training,task.type+':'+task.id,lesson.starter||'');if(task.type==='java')hideJavaHelp(task.id);}});

export const readTrainingProgress=()=>training;
export function rememberBeginnerLesson(id){if(BEGINNER_LESSON_BY_ID.has(id)&&training.learning.lastLesson!==id){training.learning.lastLesson=id;persist();}}
export const trainingStorageAvailable=()=>!storageError;
export function markBeginnerRead(id){if(!BEGINNER_LESSON_BY_ID.has(id))return false;const read=training.learning.read;training.learning.read=read.includes(id)?read.filter(value=>value!==id):[...read,id];persist();return !storageError;}
export function saveBeginnerNote(id,value){if(BEGINNER_LESSON_BY_ID.has(id)){training.learning.notes[id]=String(value).slice(0,3000);persist();return !storageError;}return false;}
export function saveBeginnerPrediction(id,value){if(BEGINNER_LESSON_BY_ID.has(id)){training.learning.predictions??={};training.learning.predictions[id]=String(value).slice(0,1500);persist();return !storageError;}return false;}
